package mz.bam.seeky.android;
import android.app.*;import android.os.*;import android.text.*;import android.view.*;import android.widget.*;import java.util.*;

/** A bounded selector: searching never materialises every row as an Android view. */
final class PagedPicker {
    static final int SIZE=40;
    static final class Entry{final String id,label,detail;Entry(String id,String label,String detail){this.id=id;this.label=label;this.detail=detail;}}
    static final class Page{final List<Entry> rows;final long total;Page(List<Entry> rows,long total){this.rows=rows;this.total=total;}}
    interface Loader{Page load(String query,int offset,int limit)throws Exception;}
    interface Pick{void choose(Entry entry);}
    static void show(Activity a,String title,Loader source,Pick selected){new PagedPicker(a,title,source,selected).show();}
    final Activity a;final Loader source;final Pick pick;final String title;final Handler main=new Handler(Looper.getMainLooper());UiDialog dialog;EditText query;TextView count,before,after;ListView list;int page,generation;
    PagedPicker(Activity a,String title,Loader source,Pick pick){this.a=a;this.title=title;this.source=source;this.pick=pick;}
    void show(){LinearLayout form=PlusUi.column(a);query=PlusUi.input(a,"Pesquisar…","",200);form.addView(query);count=PlusUi.text(a,"A carregar…",12);form.addView(count);list=new ListView(a);list.setDivider(new android.graphics.drawable.ColorDrawable(android.graphics.Color.TRANSPARENT));list.setDividerHeight(PlusUi.dp(a,10));form.addView(list,new LinearLayout.LayoutParams(-1,PlusUi.dp(a,260)));LinearLayout nav=new LinearLayout(a);before=PlusUi.text(a,"Anterior",14);after=PlusUi.text(a,"Seguinte",14);UiBox.style(before);UiBox.style(after);nav.addView(before,new LinearLayout.LayoutParams(0,-2,1));LinearLayout.LayoutParams next=new LinearLayout.LayoutParams(0,-2,1);next.leftMargin=PlusUi.dp(a,10);nav.addView(after,next);form.addView(nav);before.setOnClickListener(v->{if(page>0){page--;load();}});after.setOnClickListener(v->{page++;load();});query.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){page=0;main.removeCallbacks(refresh);main.postDelayed(refresh,200);}public void afterTextChanged(Editable e){}});dialog=new UiDialog.Builder(a).setTitle(title).setView(form).setNegativeButton("Fechar",null).create();dialog.setOnDismissListener(d->{generation++;main.removeCallbacks(refresh);});dialog.show();load();}
    final Runnable refresh=this::load;
    void load(){final int token=++generation,offset=page*SIZE;final String q=query.getText().toString();PlusUi.run(a,()->{Page result=source.load(q,offset,SIZE);PlusUi.post(a,()->{if(token!=generation||!dialog.isShowing())return;count.setText(Math.min(result.total,offset+1)+"–"+Math.min(result.total,offset+result.rows.size())+" / "+result.total);before.setEnabled(page>0);after.setEnabled(offset+result.rows.size()<result.total);list.setAdapter(new BaseAdapter(){public int getCount(){return result.rows.size();}public Object getItem(int p){return result.rows.get(p);}public long getItemId(int p){return p;}public View getView(int at,View recycled,ViewGroup parent){Entry e=result.rows.get(at);TextView v=PlusUi.text(a,"",14);v.setText(e.label+(e.detail.isEmpty()?"":"\n"+e.detail));UiBox.style(v);v.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);return v;}});list.setOnItemClickListener((parent,v,position,id)->{Entry e=result.rows.get(position);dialog.dismiss();pick.choose(e);});});});}
}
